<?php require_once("conexion.php");        /* El query valida si el usuario ingresado existe en la base de datos. Se utiliza la función      htmlentities para evitar inyecciones SQL. */	  $miusuario  = $_POST['usuario'];	  $password   = $_POST['contrasena'];	  $miuser     = htmlentities($miusuario);	  $miclave    = md5(htmlentities($password));	  $myusuario  = "SELECT idusuario FROM usuarios WHERE idusuario = '$miuser'";	  $validacion = mysqli_query($conecta,$myusuario); 	  $nmyusuario = mysqli_num_rows($validacion);      	     //Si existe el usuario, validamos también la contraseña ingresada y el estado del usuario...     if($nmyusuario != 0){	     $sql = "SELECT * FROM usuarios WHERE estado = 1 and idusuario = '$miuser' and clave = '$miclave'";             		 $myclave = mysqli_query($conecta,$sql);		 while ($nomusuario=mysqli_fetch_array($myclave)) {		 $nameusuario=$nomusuario[1];		 }			 $nmyclave = mysqli_num_rows($myclave);		 //Si el usuario y clave ingresado son correctos (y el usuario está activo en la BD), creamos la sesión del mismo.          if($nmyclave != 0){               session_start();               $_SESSION['autentica'] = "SIP";     		   $_SESSION['nombreuser'] = $nameusuario;			   $_SESSION['usuarioactual'] = $miuser; //nombre del usuario logueado.			   $user=$_SESSION['usuarioactual'];			   $ensesion="UPDATE usuarios SET login=1 WHERE idusuario='$user'";                mysqli_query($conecta,$ensesion);				$cadena=$_SESSION['usuarioactual'];				$buscar="Master";			    $palabra = stripos($cadena,$buscar);			   	if($palabra!==FALSE){			   	header("Location: principal.php");}			   	 else{				$_SESSION['autentica'] = "UTI";				header("Location: principalU.php");}                }                else{               echo"<script>alert('La contraseña del usuario no es correcta, por favor verifique');               window.location.href=\"index.php\"</script>";                }     }else{          echo"<script>alert('El usuario no existe favor de verificarlo');window.location.href=\"index.php\"</script>";     }     mysqli_close($conecta);?>